<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$_SERVER['REQUEST_METHOD']='CLI';require_once __DIR__.'/../config/db.php';$c=db();$failed=false;$checks=['adjustment amounts'=>"SELECT COUNT(*) n FROM erp_fiscal_adjustments WHERE amount<=0 OR category='' OR description='' OR legal_basis=''",'tenant ownership'=>"SELECT COUNT(*) n FROM erp_fiscal_adjustments a JOIN erp_fiscal_reconciliations r ON r.id=a.reconciliation_id WHERE a.user_id<>r.user_id",'year ranges'=>"SELECT COUNT(*) n FROM erp_fiscal_reconciliations WHERE fiscal_year NOT BETWEEN 2000 AND 2200"];
foreach($checks as $label=>$sql){$n=(int)$c->query($sql)->fetch_assoc()['n'];if($n){$failed=true;fwrite(STDERR,"FAIL $label: $n mismatch(es)\n");}else echo "PASS $label reconciles\n";}exit($failed?1:0);
